std::mutex g_log_mtx;
std::unordered_set<std::string> g_logged;
std::atomic<uint8_t*> g_mem{nullptr};
std::atomic<std::size_t> g_mem_len{0};
std::atomic<int> g_mem_warns{0};

void note_once(const std::string& tag) {
  std::lock_guard<std::mutex> lock(g_log_mtx);
  if (g_logged.insert(tag).second) {
    std::fprintf(stderr, "[import] %s\n", tag.c_str());
  }
}

bool mem_ok(uint32_t p, std::size_t n) {
  const uint8_t* base = g_mem.load(std::memory_order_acquire);
  const std::size_t len = g_mem_len.load(std::memory_order_acquire);
  return base && static_cast<std::size_t>(p) <= len && n <= len - static_cast<std::size_t>(p);
}

const uint8_t* mem_ptr(uint32_t p, std::size_t n) {
  if (!mem_ok(p, n)) {
    if (g_mem_warns.fetch_add(1) < 4) {
      std::fprintf(stderr, "[import] linear memory not bound; call wb::imports_set_memory()\n");
    }
    return nullptr;
  }
  return g_mem.load(std::memory_order_acquire) + p;
}

uint8_t* mem_mut(uint32_t p, std::size_t n) {
  if (!mem_ok(p, n)) {
    if (g_mem_warns.fetch_add(1) < 4) {
      std::fprintf(stderr, "[import] linear memory not bound; call wb::imports_set_memory()\n");
    }
    return nullptr;
  }
  return g_mem.load(std::memory_order_acquire) + p;
}

std::string mem_cstr(uint32_t p, std::size_t cap = 16384) {
  const uint8_t* q = mem_ptr(p, 1);
  if (!q) return {};
  const std::size_t max = std::min<std::size_t>(cap, g_mem_len.load() - p);
  const void* end = std::memchr(q, 0, max);
  const std::size_t n = end ? static_cast<const uint8_t*>(end) - q : max;
  return std::string(reinterpret_cast<const char*>(q), n);
}

bool mem_write(uint32_t p, const void* src, std::size_t n) {
  uint8_t* dst = mem_mut(p, n);
  if (!dst) return false;
  if (n) std::memcpy(dst, src, n);
  return true;
}

uint32_t mem_ld32(uint32_t p) {
  const uint8_t* q = mem_ptr(p, 4);
  uint32_t v = 0;
  if (q) std::memcpy(&v, q, 4);
  return v;
}

void mem_st32(uint32_t p, uint32_t v) {
  mem_write(p, &v, 4);
}

uint64_t mem_ld64(uint32_t p) {
  const uint8_t* q = mem_ptr(p, 8);
  uint64_t v = 0;
  if (q) std::memcpy(&v, q, 8);
  return v;
}

double steady_ms() {
  using clock = std::chrono::steady_clock;
  static const auto origin = clock::now();
  // Match v2-wasmtime: start at 1000 ms so timers ordered before boot stay
  // positive, while the clock still advances monotonically.
  return 1000.0 + std::chrono::duration<double, std::milli>(clock::now() - origin).count();
}

double wall_ms() {
  return std::chrono::duration<double, std::milli>(
             std::chrono::system_clock::now().time_since_epoch()).count();
}

int cpu_count() {
  const unsigned n = std::thread::hardware_concurrency();
  return n ? static_cast<int>(n) : 1;
}

// --- embind -----------------------------------------------------------------
Binding g_bindings[512];
std::size_t g_nbindings = 0;
std::mutex g_bind_mtx;
std::unordered_map<uint32_t, std::string> g_types;

void bind_type(uint32_t id, const char* kind) {
  std::lock_guard<std::mutex> lock(g_bind_mtx);
  g_types[id] = kind;
}

void add_binding(const std::string& name, const std::string& sig,
                 uint32_t argc, uint32_t invoker, uint32_t id) {
  std::lock_guard<std::mutex> lock(g_bind_mtx);
  if (g_nbindings >= std::size(g_bindings) || name.empty() || !invoker) return;
  Binding& b = g_bindings[g_nbindings++];
  std::memset(&b, 0, sizeof b);
  std::snprintf(b.name, sizeof b.name, "%s", name.c_str());
  std::snprintf(b.sig, sizeof b.sig, "%s", sig.c_str());
  b.argc = argc ? argc - 1 : 0;  // argc includes the receiver placeholder
  b.invoker = invoker;
  b.id = id;
}

// --- fetch / HTTP (libcurl) --------------------------------------------------
constexpr std::size_t kMaxFetch = 256u << 20;

struct HeaderEntry {
  uint32_t fetch;
  std::string text;
};
std::vector<HeaderEntry> g_headers;
std::mutex g_headers_mtx;

void store_headers(uint32_t fetch, const std::string& text) {
  std::lock_guard<std::mutex> lock(g_headers_mtx);
  for (HeaderEntry& h : g_headers) {
    if (h.fetch == fetch) {
      h.text = text;
      return;
    }
  }
  if (g_headers.size() < 64) g_headers.push_back({fetch, text});
}

std::size_t write_body(char* data, std::size_t size, std::size_t nmemb, void* user) {
  auto* out = static_cast<std::vector<uint8_t>*>(user);
  const std::size_t n = size * nmemb;
  if (n > kMaxFetch - out->size()) return 0;
  out->insert(out->end(), data, data + n);
  return n;
}

std::size_t write_header(char* data, std::size_t size, std::size_t nmemb, void* user) {
  auto* out = static_cast<std::string*>(user);
  out->append(data, size * nmemb);
  return size * nmemb;
}

bool http_get(const std::string& url, std::vector<uint8_t>& out, std::string* headers) {
  static const bool curl_ready = [] {
    curl_global_init(CURL_GLOBAL_DEFAULT);
    return true;
  }();
  (void)curl_ready;
  if (url.empty()) return false;
  CURL* curl = curl_easy_init();
  if (!curl) return false;
  const char* ua = std::getenv("WC_UA");
  curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
  curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
  curl_easy_setopt(curl, CURLOPT_FAILONERROR, 1L);
  curl_easy_setopt(curl, CURLOPT_TIMEOUT, 120L);
  curl_easy_setopt(curl, CURLOPT_USERAGENT, ua ? ua : "Roblox/Darwin");
  curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, &write_body);
  curl_easy_setopt(curl, CURLOPT_WRITEDATA, static_cast<void*>(&out));
  if (headers) {
    curl_easy_setopt(curl, CURLOPT_HEADERFUNCTION, &write_header);
    curl_easy_setopt(curl, CURLOPT_HEADERDATA, static_cast<void*>(headers));
  }
  const CURLcode rc = curl_easy_perform(curl);
  long status = 0;
  curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &status);
  curl_easy_cleanup(curl);
  return rc == CURLE_OK && status >= 200 && status < 300;
}

std::string content_root() {
  const char* env = std::getenv("WC_CONTENT");
  return env && *env ? env : "data/content";
}

// Map an engine URL onto a local mirror path.  Reject traversal and schemes
// that can never be mirrored, exactly like v3-wasm2c/fetch.c.
bool resolve_url(const std::string& url, std::string& path) {
  std::string u = url;
  if (u.rfind("data:", 0) == 0 || u.rfind("rbxthumb://", 0) == 0) return false;
  if (u.rfind("http://", 0) == 0 || u.rfind("https://", 0) == 0) {
    const std::size_t scheme = u.find("://") + 3;
    const std::size_t slash = u.find('/', scheme);
    u = slash == std::string::npos ? "/" : u.substr(slash);
  }
  if (u.rfind("rbxasset://", 0) == 0) u = u.substr(11);
  while (!u.empty() && u[0] == '/') u.erase(u.begin());
  if (u.empty() || u.find("..") != std::string::npos) return false;
  path = content_root() + "/" + u;
  return true;
}

bool read_file(const std::string& path, std::vector<uint8_t>& out) {
  std::FILE* f = std::fopen(path.c_str(), "rb");
  if (!f) return false;
  std::fseek(f, 0, SEEK_END);
  const long size = std::ftell(f);
  std::fseek(f, 0, SEEK_SET);
  if (size < 0 || static_cast<std::size_t>(size) > kMaxFetch) {
    std::fclose(f);
    return false;
  }
  out.resize(static_cast<std::size_t>(size));
  const std::size_t got = out.empty() ? 0
      : std::fread(out.data(), 1, out.size(), f);
  std::fclose(f);
  out.resize(got);
  return got == static_cast<std::size_t>(size);
}

void write_file(const std::string& path, const std::vector<uint8_t>& data) {
  const std::size_t slash = path.find_last_of('/');
  if (slash != std::string::npos) {
    std::string dir = path.substr(0, slash);
    for (std::size_t i = 1; i < dir.size(); ++i) {
      if (dir[i] == '/') {
        ::mkdir(dir.substr(0, i).c_str(), 0777);
      }
    }
    ::mkdir(dir.c_str(), 0777);
  }
  std::FILE* f = std::fopen(path.c_str(), "wb");
  if (!f) return;
  if (!data.empty()) std::fwrite(data.data(), 1, data.size(), f);
  std::fclose(f);
}

std::string remote_url(const std::string& url) {
  if (url.rfind("http://", 0) == 0 || url.rfind("https://", 0) == 0) return url;
  const char* base = std::getenv("WC_BASE");
  if (!base) base = std::getenv("WC_BASE_URL");
  if (!base || !*base) return {};
  std::string u = url;
  if (u.rfind("rbxasset://", 0) == 0) u = u.substr(11);
  while (!u.empty() && u[0] == '/') u.erase(u.begin());
  return std::string(base) + u;
}

