// Defined below, after the futex helpers; used by the mailbox ring wake-up.
uint32_t imports_futex_notify(uint32_t addr, uint32_t count);

// --- public integration API ------------------------------------------------
void imports_set_memory(void* base, std::size_t length) {
  g_mem.store(static_cast<uint8_t*>(base), std::memory_order_release);
  g_mem_len.store(length, std::memory_order_release);
}

bool imports_has_memory() {
  return g_mem.load(std::memory_order_acquire) != nullptr;
}

void imports_install(FunctionImportSlot* slots, std::size_t count, void* import_vmctx) {
  static_assert(sizeof(FunctionImportSlot) == 32, "VMFunctionImport ABI mirror");
  if (!slots) return;
  for (std::size_t i = 0; i < count && i < kImportCount; ++i) {
    slots[i].array_call = nullptr;  // no array-to-wasm trampoline in out.full.o
    slots[i].wasm_call = g_calls[i];
    slots[i].type_index = g_descs[i].type_index;
    slots[i].reserved = 0;
    slots[i].vmctx = import_vmctx;
  }
}

const Binding* embind_bindings() { return g_bindings; }
std::size_t embind_binding_count() {
  std::lock_guard<std::mutex> lock(g_bind_mtx);
  return g_nbindings;
}
const Binding* embind_find(const char* name) {
  if (!name) return nullptr;
  std::lock_guard<std::mutex> lock(g_bind_mtx);
  for (std::size_t i = 0; i < g_nbindings; ++i) {
    if (!std::strcmp(g_bindings[i].name, name)) return &g_bindings[i];
  }
  return nullptr;
}
const char* embind_type(uint32_t id) {
  std::lock_guard<std::mutex> lock(g_bind_mtx);
  auto it = g_types.find(id);
  return it == g_types.end() ? nullptr : it->second.c_str();
}

void imports_set_thread_entry(ThreadEntry entry) { g_thread_entry = entry; }
void imports_set_guest_tick(GuestTick fn) { g_guest_tick = fn; }
void imports_set_wasm_callback(WasmCallback cb) { g_wasm_cb = cb; }
void imports_set_main_thread(uint32_t pthread_ptr) { g_main_thread = pthread_ptr; }
void imports_set_main_thread_init(MainThreadInit fn) { g_main_thread_init = fn; }

void imports_store_headers(uint32_t fetch, const char* text) {
  store_headers(fetch, text ? text : "");
}

uint32_t imports_futex_notify(uint32_t addr, uint32_t count) {
  std::shared_ptr<Waiter> w;
  {
    std::lock_guard<std::mutex> lock(g_waiters_mtx);
    auto it = g_waiters.find(addr);
    if (it == g_waiters.end()) return 0;
    w = it->second;
  }
  std::lock_guard<std::mutex> lock(w->m);
  if (!w->signaled) {
    w->signaled = true;
    w->cv.notify_all();
    return 1;
  }
  (void)count;
  return 0;
}

