// slot 3: js_fetch_file -- local asset mirror, libcurl fallback -------------
extern "C" int32_t wasm_import_003_js_fetch_file(void* vmctx, void* caller_vmctx, int32_t a1, int32_t a2, int32_t a3) {
  WB_TRACE_IMPORT(3);
  (void)caller_vmctx;
  (void)vmctx;
  const std::string url = wb::mem_cstr(a1);
  const uint32_t dst = static_cast<uint32_t>(a2);
  const uint32_t want = static_cast<uint32_t>(a3);
  wb::note_once("[fetch] first js_fetch_file: " + url);
  if (url.empty()) return static_cast<int32_t>(-1);

  std::string path;
  if (!wb::resolve_url(url, path)) return static_cast<int32_t>(-1);
  std::vector<uint8_t> body;
  if (wb::read_file(path, body) && (!want || body.size() == want)) {
    if (!wb::mem_write(dst, body.data(), body.size())) return static_cast<int32_t>(-1);
    return 0;
  }
  const std::string remote = wb::remote_url(url);
  if (remote.empty()) return static_cast<int32_t>(-2);
  std::vector<uint8_t> fetched;
  if (!wb::http_get(remote, fetched, nullptr)) return static_cast<int32_t>(-1);
  if (want && fetched.size() != want) return static_cast<int32_t>(-1);
  wb::write_file(path, fetched);
  if (!wb::mem_write(dst, fetched.data(), fetched.size())) return static_cast<int32_t>(-1);
  return 0;
}

// slot 4: engine performance clock -----------------------------------------
extern "C" double wasm_import_004_emscripten_get_now(void* vmctx, void* caller_vmctx) {
  WB_TRACE_IMPORT(4);
  (void)caller_vmctx;
  // A guest turn at its clock: hand over one native RNA completion, exactly
  // one per invocation (the bridge has a re-entrancy guard).
  if (wb::g_guest_tick) wb::g_guest_tick(vmctx);
  // Safe point for a pending mailbox ring (Rust's mailbox::pump_now).  No-op
  // unless a notify actually arrived; never re-enters wasm on a worker.
  wb::mailbox_drain_if_pending(vmctx);
  return wb::steady_ms();
}

// slot 5: Atomics.waitAsync -- host futex with notify hook ------------------
extern "C" int32_t wasm_import_005___asyncjs__rbxFutexWaitMainJspi(
    void* vmctx, void* caller_vmctx, int32_t a1, int32_t a2, double a3) {
  WB_TRACE_IMPORT(5);
  (void)caller_vmctx;
  if (wb::g_guest_tick) wb::g_guest_tick(vmctx);
  wb::mailbox_drain_if_pending(vmctx);
  const uint32_t addr = static_cast<uint32_t>(a1);
  const uint32_t expected = static_cast<uint32_t>(a2);
  const uint8_t* word = wb::mem_ptr(addr, 4);
  if (!word) return 1;
  uint32_t cur = 0;
  std::memcpy(&cur, word, 4);
  if (cur != expected) return 1;  // not-equal

  const auto w = wb::waiter_for(addr);
  auto deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(2);
  const bool bounded = a3 > 0.0 && a3 < 1e12;
  if (bounded) {
    deadline = std::chrono::steady_clock::now() +
               std::chrono::duration_cast<std::chrono::steady_clock::duration>(
                   std::chrono::duration<double, std::milli>(a3));
  } else {
    wb::note_once("[futex] unbounded wait: polling in 2 ms slices");
  }
  // Never spin forever if a notifier is missing: the page would keep running
  // its event loop, this host has no fibre pump.
  const auto hard_stop = std::chrono::steady_clock::now() + std::chrono::seconds(30);
  for (;;) {
    std::unique_lock<std::mutex> lock(w->m);
    w->cv.wait_until(lock, std::min(deadline, hard_stop), [&] { return w->signaled; });
    const bool woke = w->signaled;
    w->signaled = false;
    lock.unlock();
    cur = *reinterpret_cast<const uint32_t*>(wb::mem_ptr(addr, 4));
    if (cur != expected) return 0;  // woken
    if (woke) return 0;             // notify without a word change
    if (bounded && std::chrono::steady_clock::now() >= deadline) return 2;  // timed out
    if (std::chrono::steady_clock::now() >= hard_stop) return 2;
    deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(2);
  }
}

